import {rng,iso,day} from './expert-stats.mjs?v=20261102-expert1';
export function makeExpertDemo(){const random=rng(20261102),start=day('2025-01-01'),event=iso(start+60);const wells=[{well_id:'I-01',x_m:0,y_m:0,type:'注入井',depth_m:2120},...Array.from({length:5},(_,i)=>({well_id:'P-0'+(i+1),x_m:250+80*i,y_m:120*(i%2?1:-1),type:'生产井',depth_m:2120}))],layers=[{layer:'S1',top_m:2100,bottom_m:2140,porosity:.23,perm_md:180,initial_pressure_mpa:27,remaining_oil_sat:.32,temperature_c:72,ooip_m3:5000000},{layer:'S2',top_m:2140,bottom_m:2190,porosity:.18,perm_md:45,initial_pressure_mpa:28,remaining_oil_sat:.39,temperature_c:76,ooip_m3:3500000}],types=['压裂','酸化','CO₂驱','聚合物驱','调剖调驱'];const interventions=types.map((type,i)=>({id:'DEMO-J'+(i+1),well_id:'P-0'+(i+1),layer:i%2?'S2':'S1',type,date:event,fluid_m3:600+300*i,proppant_t:type==='压裂'?65:null,acid_m3:type==='酸化'?150:null,breakdown_mpa:34+i,peak_treating_mpa:38+i,frac_half_length_m:type==='压裂'?120:null,frac_height_m:type==='压裂'?24:null,conductivity_md_m:null,acid_radius_m:type==='酸化'?6:null,flowback_start_date:iso(start+61),flowback_end_date:iso(start+67),first_oil_date:iso(start+64),flowback_m3:200+30*i,co2_injected_t:type==='CO₂驱'?1200:null,polymer_conc_mg_l:type==='聚合物驱'?1500:null,polymer_injected_t:type==='聚合物驱'?18:null,monitoring_note:'人工构造作业记录；支撑导流能力未设置，不把微地震包络作为有效支撑证据。'}));const production=[];for(let t=0;t<120;t++){production.push({well_id:'I-01',date:iso(start+t),injection_m3_d:600+80*Math.sin(t/10),pressure:23+Math.sin(t/11)});for(let i=0;i<5;i++){const after=t>=60,response=after?([40,25,20,35,18][i])*(1-Math.exp(-(t-60)/8)):0;production.push({well_id:'P-0'+(i+1),date:iso(start+t),oil:Math.max(0,180-15*i-.4*t+response+(random()-.5)*14),water:Math.max(0,80+10*i+.3*t-(after?8*i:0)+(random()-.5)*8),gas:15000+800*i+response*80+(random()-.5)*1200,pressure:23-.018*t+(after?1+.15*i:0)+(random()-.5)*.3,injection_co2_t:i===2&&after?20:0,polymer_kg_d:i===3&&after?300:0});}}
const tracer=[];for(let i=0;i<5;i++)for(let t=0;t<=30;t++){const mu=3+3*i,sigma=1.2+i*.3;tracer.push({injector:'I-01',producer:'P-0'+(i+1),tracer_id:'FBA-DEMO',layer_from:'S1',layer_to:i===1?'S2':'S1',injection_date:event,time_days:t,concentration_mg_l:t===0?0:.1*Math.exp(-.5*((t-mu)/sigma)**2),rate_m3_d:500,injected_mass_kg:2,distance_m:Math.hypot(wells[i+1].x_m,wells[i+1].y_m),lod_mg_l:.015,concentration_sd_mg_l:.003,rate_rel_sd:.05,distance_sd_m:5,injected_mass_sd_kg:.1});}const micro=Array.from({length:140},(_,i)=>({well_id:'P-01',job_id:'DEMO-J1',event_time:event+'T12:00:00Z',x_m:250+(random()-.5)*260,y_m:-120+(random()-.5)*90,z_m:2120+(random()-.5)*60,sigma_m:5+random()*4,magnitude:-2+random()}));return {schema_version:1,synthetic:true,source:'人工构造教学场景（非Volve配套、非现场实测）',wells,layers,production,interventions,tracer,micro,cases:[],other:[{producer:'P-02',layer_from:'S1',layer_to:'S2',method:'压力干扰解释',date:event,result:'教学线索：压力响应可见，井筒混流未排除',source:'人工解释示例，不作为现场证据'}]};}
